INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1048, 'koKR', '%s wzywa z cienia kolejnych sojuszników.', '', 0),
(1146, 'koKR', 'Ruszać się, te części mają trafić na statek!', '', 0),
(1147, 'koKR', 'Ktoś chce przerwę? No to pech! Do roboty, gamonie!', '', 0),
(1148, 'koKR', 'Ty tam! Sprawdź, co to za hałas!', 'Ty tam! Sprawdź, co to za hałas!', 0),
(1149, 'koKR', 'Atakują nas! Ahoj, szczury pokładowe! Odeprzeć najeźdźców!', 'Atakują nas! Ahoj, szczury pokładowe! Odeprzeć najeźdźców!', 0),
(1327, 'koKR', '%s wyskakuje z cienia!', '%s wyskakuje z cienia!', 0),
(1344, 'koKR', 'Szczury lądowe z was twardsze, niż myślałem! Trzeba będzie coś wymyślić!', 'Szczury lądowe z was twardsze, niż myślałem! Trzeba będzie coś wymyślić!', 0),
(1345, 'koKR', 'Arrr! Teraz mnie rozzłościliście!', 'Arrr! Teraz mnie rozzłościliście!', 0),
(5619, 'koKR', 'VanCleef dużo płacić za wasze głowy!', '', 0),
(6061, 'koKR', 'Nikt nie rzuci wyzwania Bractwu!', '', 0),
(6062, 'koKR', 'I leż!', '', 0),
(6063, 'koKR', 'Pieski na smyczy, wszyscy co do jednego!', '', 0),
(6064, 'koKR', 'Głupcy! Nasza sprawa jest słuszna!', '', 0),
